{
  "title": "The Mirror Glass Rescue",
  "gate_token": "1z-Fxmg_Mo5_U-m5jatYgg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined city.",
      "visual_description": "Mara spreads a stained parchment map across a broken stone table under a gray sky, the city's towers visible in the distance.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Glass Diver gleams beside a shattered window.",
      "visual_description": "Glass Diver stands near a tall broken window, his diving helmet reflecting the cracked glass and distant buildings.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp flickers a warning about the castle gates.",
      "visual_description": "Oracle Lamp sits on a fallen pillar, its single flame eye bright as it casts shadows on the rusted castle gates behind it.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scampers ahead to scout the gates.",
      "visual_description": "Tin Fox moves silently through rubble, its blue eyes glowing as it approaches the massive iron gates draped with torn royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Sleeping Tax Collector naps on a stack of ledgers by the gate.",
      "visual_description": "Sleeping Tax Collector snores softly, his head resting on a ledger book, stamped papers fluttering around him near the gate's base.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks the gate as passable on her map.",
      "visual_description": "Mara kneels by the gate, dipping a quill into ink while Glass Diver watches, the Oracle Lamp hovering nearby.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox discovers a cursed tower entrance.",
      "visual_description": "Tin Fox stands before a twisted tower door covered in glowing runes, its tail winding nervously.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp warns of the tower's curse.",
      "visual_description": "Oracle Lamp's flame eye pulses red as it hovers in front of the tower door, shadows writhing on the stone.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver swims through a mirror into the tower.",
      "visual_description": "Glass Diver presses his helmet against a cracked mirror and steps through, rippling like water into the tower's dark interior.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara consults her map inside the tower.",
      "visual_description": "Mara holds a lantern as she traces a path on her map, surrounded by dusty shelves and cobwebbed relics.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Tin Fox dodges a falling portcullis in a corridor.",
      "visual_description": "Tin Fox rolls under a descending portcullis, sparks flying from its metal legs, blue eyes wide.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Sleeping Tax Collector is carried along, still asleep.",
      "visual_description": "Glass Diver carries the snoring Sleeping Tax Collector over his shoulder through a narrow passage, papers trailing behind.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp reveals a magic door with a riddle.",
      "visual_description": "Oracle Lamp illuminates a stone door covered in shifting symbols, its flame eye reading the patterns.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara solves the riddle and the door opens.",
      "visual_description": "Mara traces a symbol on the door, which groans open to reveal a hallway leading to the city walls.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The group emerges onto a bridge over a chasm.",
      "visual_description": "The team steps onto a crumbling stone bridge, mist rising from the deep chasm below, old banners hanging from the railings.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols appear at the bridge's far end.",
      "visual_description": "Figures in dark armor march onto the bridge from the opposite side, their torches casting long shadows.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "Glass Diver shatters a section of the bridge behind them.",
      "visual_description": "Glass Diver strikes the bridge stones with a shard of mirror, collapsing the path and halting the patrols.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes into the mist beyond the bridge.",
      "visual_description": "The team runs across the remaining bridge and disappears into a bank of fog, leaving the ruined city behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

